"Minecraft Java 版用的是 OpenGL，国产显卡的 OpenGL 驱动还在快速完善，档次是按型号推算的。遇到花屏、黑屏、打不开或光影出错：先到官网更新到最新驱动；还不行可以先关掉光影、用 Sodium 这类优化 Mod，或者换旧一点的游戏版本试试": "Minecraft: Java Edition uses OpenGL, and OpenGL drivers for Chinese GPUs are still maturing; the tier is estimated from the model. If you get garbled or black screens, crashes or shader errors: update to the latest driver from the official site first; if that doesn't help, turn off shaders, use optimization mods like Sodium, or try an older game version",
