"Minecraft Java 版需要 Java 才能运行，这台电脑上还没有找到。推荐安装 Mojang 官方的 Java 21（约 50 MB），它能运行 1.17 到 1.21 的所有版本。": "Minecraft: Java Edition needs Java to run, and none was found on this PC. Installing Mojang's official Java 21 (about 50 MB) is recommended; it runs every version from 1.17 to 1.21.",
