"OptiFine 不支持 NeoForge，推荐改用 Embeddium + Oculus": "OptiFine doesn't support NeoForge; use Embeddium + Oculus instead",
"OptiFine 不是为 Fabric 做的，要靠 OptiFabric 转接，和很多 Mod（尤其是 Sodium）冲突。更推荐用 Sodium + Iris。仍然安装会把 OptiFine 和 OptiFabric 一起放进 mods。": "OptiFine isn't made for Fabric; it needs OptiFabric as a bridge and conflicts with many mods (Sodium especially). Sodium + Iris is the better choice. Installing anyway puts OptiFine and OptiFabric in mods.",
"OptiFine 会作为加载器装进这个配置（不新建配置），之后可以在「组件」区卸载或撤销。": "OptiFine will be installed into this profile as its loader (no new profile). You can uninstall or undo it later in the \"Components\" section.",
