"Parallels（Mac）：3D 加速默认是开的，Minecraft 能跑但虚拟显卡性能有限；在 macOS 上直接用官方启动器玩 Minecraft 会流畅得多（原生支持苹果芯片）": "Parallels (Mac): 3D acceleration is on by default and Minecraft runs, but virtual graphics are limited; playing Minecraft on macOS with the official launcher is much smoother (it supports Apple silicon natively)",
"Prism / MultiMC 的配置要联网重新安装游戏和加载器，需要几分钟": "Prism / MultiMC profiles need the game and loader installed again online. This takes a few minutes",
"QEMU / KVM：QXL、virtio-gpu 默认没有 OpenGL 3.2，Minecraft 1.17 起打不开；可以用显卡直通（VFIO），或者试试 virgl（virtio-gpu-gl）": "QEMU / KVM: QXL and virtio-gpu have no OpenGL 3.2 by default, so Minecraft 1.17+ won't start; use GPU passthrough (VFIO), or try virgl (virtio-gpu-gl)",
