"{0}会多次启动游戏：每轮禁用一半的 Mod，观察是否还会崩溃，从而定位出问题的 Mod。\n\n· 每轮约 30 秒 ~ 2 分钟，期间会弹出游戏窗口\n· 排查结束后会恢复所有 Mod 的启用状态\n· 可以随时在右上角的任务面板中取消\n\n{1}\n{2}": "{0} launches the game several times: each round disables half of the mods and watches whether it still crashes, narrowing down the problem mod.\n\n· Each round takes about 30 s to 2 min, and a game window pops up meanwhile\n· When it's done, every mod's enabled state is restored\n· You can cancel any time in the task panel at the top right\n\n{1}\n{2}",
