"“存档隔离 / 共享 / 测试副本”“二分排查”“Mod 管理”“整合包安装”等功能会创建、移动、重命名或删除本地文件。建议用户在使用前自行备份重要的存档与配置。": "Features such as save isolation / sharing / test copies, bisect troubleshooting, mod management and modpack installation create, move, rename or delete local files. Back up important saves and settings yourself before using them.",
