"① 游戏窗口跑到看不见的屏幕上：{0}是虚拟显示器，可能被当成了主屏。在 Windows 设置 → 系统 → 屏幕里把真实显示器设为主显示器，或者在软件里关掉虚拟显示器 / 无显示器模式": "① The game window opens on a screen you can't see: {0} is a virtual display and may be treated as the main screen. Set your real monitor as the main display in Windows Settings → System → Display, or turn off the virtual display / headless mode in the software",
"① 游戏窗口跑到看不见的屏幕上：有的软件会装虚拟显示器，被当成主屏时会这样。在 Windows 设置 → 系统 → 屏幕里把真实显示器设为主显示器": "① The game window opens on a screen you can't see: some software installs a virtual display, which causes this when it becomes the main screen. Set your real monitor as the main display in Windows Settings → System → Display",
"② 远程画面黑屏或卡住：游戏改成窗口化（F11 退出全屏），或者在软件里换一种画面采集方式 / 打开硬件编码": "② The remote picture is black or frozen: run the game windowed (F11 leaves fullscreen), or switch the capture method / turn on hardware encoding in the software",
"③ 远程操作时视角乱转、鼠标不跟手：在软件里打开游戏模式 / 锁定鼠标，或者在游戏「选项 → 控制 → 鼠标设置」里关掉「原始输入」": "③ The camera spins or the mouse lags when remote: turn on game mode / mouse lock in the software, or turn off \"Raw Input\" in the game's \"Options → Controls → Mouse Settings\"",
