"「{0}」上次装到一半就中断了（可能是启动器被关掉或电脑断电），现在玩不了。删掉以后可以重新安装；也可以先留着，以后自己在配置里删除。": "\"{0}\" stopped halfway through installing last time (the launcher may have been closed or the PC lost power), so it can't be played. Delete it and you can install it again, or keep it for now and delete it from the profile later.",
