"从旧电脑的导出包、或者这台电脑上的另一套 Aurora 数据，把游戏配置、存档、设置搬过来。不需要的话直接跳过": "Bring profiles, saves and settings over from an old PC's export package, or from another set of Aurora data on this PC. Skip this if you don't need it",
