"从皮肤库删除「{0}」？已经用着这张皮肤的账户不受影响。": "Delete \"{0}\" from the skin library? Accounts already using this skin aren't affected.",
"从第三方渠道获取并使用本启动器或其修改版所造成的一切损失与后果（包括但不限于账户被盗、数据泄露、设备感染恶意程序），均由用户与该渠道的发布者自行承担，原版开发者不承担任何责任。请仅从作者公布的官方渠道获取本程序。": "All losses and consequences of obtaining and using the launcher or a modified version from third-party channels (including but not limited to stolen accounts, data leaks and malware) are borne by the user and the publisher of that channel; the original developer takes no responsibility. Only get this program from the channels the author has announced.",
