"以「{0}」启动：每次启动复制": "Launch as \"{0}\": copy on every launch",
"以上三项一起清除（不影响已安装的游戏、Mod 和存档，也不影响 MC 百科中文信息缓存）": "Clears all three above (installed games, mods and saves aren't affected)",
"以上信息保存在版本目录下的 aurora-profile.json（{0}格式 v{1}），{2}时会一并带上。": "This info is stored in aurora-profile.json in the version folder ({0} format v{1}) and is included when you {2}.",
"以下是启动器的初步分析": "Here is the launcher's first analysis",
"以后再说": "Later",
"以后再说也没关系：启动游戏时会自动下载这个版本需要的 Java。": "Later is fine too: the Java a version needs is downloaded automatically when you start the game.",
"以后新建游戏配置时默认选中哪一种，新建时也可以改": "Which one is selected by default for new profiles; you can still change it when creating one",
"以后新建的游戏配置，存档怎么放？": "How should saves be stored for new profiles?",
"以后这个配置的存档、Mod 配置、游戏选项、光影包都只属于它自己，和「{0}」互不影响。现在用的内容会留下来：": "From now on, this profile's saves, mod configs, game options and shader packs belong only to it, independent of \"{0}\". What's in use now is kept:",
"以后都用 Java {n}": "Always use Java {n}",
"任务": "Tasks",
"任务中心": "Task Center",
"任务仍在进行中": "The task is still running",
"任意版本": "Any version",
"会依次检查下面几项，最后真的启动一次游戏，进入主菜单后自动关掉，不用手动退出。\n{0}": "Checks the items below one by one, then really launches the game once and closes it automatically at the main menu — no need to quit yourself.\n{0}",
"会先检查文件是哪个版本的启动器导出的、内容有没有损坏或被改动过": "First checks which launcher version exported the file and whether its content is damaged or modified",
"会复制这个配置的 Mod 与配置（不复制存档），存档使用原配置存档的{0}。你可以放心地在副本里更新 Mod，确认没问题后再更新原配置。": "Copies this profile's mods and configs (not saves); saves use {0} of the original profile's saves. You can update mods in the copy safely, then update the original once everything checks out.",
"会导致启动失败或设置全乱。备份后让游戏重新生成默认设置（画质、按键会恢复默认）": "It makes launching fail or scrambles the settings. Back it up and let the game create default settings again (graphics and controls go back to default)",
"会整个替换成备份里的内容": "Will be replaced entirely by the backup's content",
"会替换现在的主题、内存、下载源等设置；数据位置、游戏目录不会变": "Replaces the current theme, memory, download source and other settings; the data location and game folder stay the same",
"会禁用": "Will be disabled",
"会移动到回收站，可以从回收站恢复。": "Moves to the Recycle Bin and can be restored from there.",
"会被替换成备份时的样子": "Will be replaced with how it was at backup time",
"会读取其中的 Mod 列表作为方案的基础，你可以再自由增删、换版本": "Its mod list becomes the base of the plan; you can freely add, remove and change versions",
"会通过文件哈希在 Modrinth 上查找每个 Mod": "Each mod is looked up on Modrinth by file hash",
