"作者关闭了第三方下载：安装时会请你在浏览器里下载这个文件，下载好后启动器自动放进配置": "The author turned off third-party downloads: when installing you'll be asked to download this file in your browser, and the launcher puts it into the profile automatically",
"作者关闭了第三方下载：请在网页上下载整合包，再用「导入整合包」安装": "The author turned off third-party downloads: download the modpack from the website, then install it with \"Import modpack\"",
"作者可能随版本更新修改本声明，更新后的声明自发布之日起生效；声明内容发生变化时，本启动器会再次请求你确认。继续使用即视为接受更新后的声明，如不同意，请停止使用并删除本启动器。": "The author may update this statement with new versions; the updated statement takes effect on release, and the launcher will ask you to confirm again when it changes. Continuing to use the launcher means you accept the updated statement; if you don't agree, stop using and delete it.",
"作者无法控制从第三方渠道（包括但不限于网盘、论坛、群文件，以及 GitHub 等平台上基于原版代码修改后发布的版本）获取的程序是否被植入恶意代码或被篡改。": "The author can't control whether programs obtained from third-party channels (including but not limited to cloud drives, forums, group files, and versions modified from the original code and published on platforms like GitHub) have been tampered with or contain malicious code.",
