"去掉忽明忽暗和突然变亮的效果：爆炸白光、烟花、流星、生物受伤闪白、苦力怕闪烁、萤火虫明暗、启动按钮流光、黄色标语跳动": "Removes flickering and sudden brightness: explosion flashes, fireworks, shooting stars, mobs flashing white when hurt, creeper blinking, fireflies, the launch button shine, the bouncing yellow splash text",
