"参数不对": "Invalid arguments",
"参考 HMCL 的 OptiFineInstallTask 的思路：用 OptiFine 自带的 Patcher 生成库文件，再用 LaunchWrapper 启动。代码是自己写的，OptiFine 文件来自 BMCLAPI 镜像": "Follows the approach of HMCL's OptiFineInstallTask: generate libraries with OptiFine's own Patcher, then launch through LaunchWrapper. The code is our own; OptiFine files come from the BMCLAPI mirror",
"参考与致谢": "References & Acknowledgements",
"参考了 HMCL 的 YggdrasilServer 有哪些接口、怎么组织，代码是自己写的。协议是 authlib-injector 公开的 Yggdrasil 服务端规范": "Referenced which endpoints HMCL's YggdrasilServer has and how they're organized; the code is our own. The protocol is authlib-injector's public Yggdrasil server specification",
"参考实现": "Reference implementation",
