"听障玩家可以用 Windows 11 的实时辅助字幕，把电脑里播放的声音转成文字（Win + Ctrl + L）": "Players who are deaf or hard of hearing can use Windows 11 Live Captions to turn sound playing on the PC into text (Win + Ctrl + L)",
"启动": "Launch",
"启动 {0}": "Launch {0}",
"启动、测试或运行游戏时自动暂停": "Pause automatically when launching, testing or running the game",
