"启动后直接连接到指定服务器": "Connect to a server right after launching",
"启动器": "Launcher",
"启动器下载的 Java": "Java downloaded by the launcher",
"启动器下载的 Java、账户、设置与{0}的{1}会一起复制": "Java downloaded by the launcher, accounts, settings and {1} of {0} are copied together",
"启动器不会绕过作者的设置：安装时会列出这些文件，请你在浏览器里下载，下载好后自动放进配置": "The launcher won't bypass the author's choice: these files are listed when installing, you download them in your browser, and they're put into the profile automatically",
"启动器不收集任何数据：没有统计、没有遥测、不上传你的任何信息，也没有自己的后台服务器。": "The launcher collects no data: no analytics, no telemetry, nothing about you is uploaded, and it has no server of its own.",
"启动器不检测版本更新。新版本请到作者发布的 GitHub 仓库或其他发布位置自行获取。": "The launcher doesn't check for updates. Get new versions yourself from the author's GitHub repository or other release locations.",
"启动器从画面上认出的字": "Text the launcher read from the screen",
"启动器会以测试模式启动一次游戏，检测能否顺利进入主菜单，并分析日志中的错误。\n{0}\n{1}": "The launcher starts the game once in test mode, checks that it reaches the main menu, and analyzes errors in the log.\n{0}\n{1}",
"启动器会根据版本自动选择合适的 Java，缺失时可自动下载": "The launcher picks a suitable Java for each version automatically and can download it when missing",
"启动器会自动判断结果：游戏进入主菜单、稳定运行十几秒就算通过，随后自动关闭游戏窗口并读取日志，不需要你手动退出。": "The launcher judges the result automatically: reaching the main menu and running steadily for a dozen seconds counts as a pass, then it closes the game window and reads the log — you don't need to quit yourself.",
"启动器初始化失败": "The launcher failed to start",
"启动器外面开的游戏「{0}」正在运行，先关掉游戏再{1}": "\"{0}\", started outside the launcher, is running. Close the game before you {1}",
"启动器外面开的游戏正在运行，先关掉游戏再{0}": "A game started outside the launcher is running. Close it before you {0}",
"启动器放的位置不太合适": "The launcher's location isn't ideal",
"启动器放的位置可能会丢数据": "The launcher's location could lose data",
"启动器数据": "Launcher data",
"启动器数据、Java、游戏、Mod 与存档全部放进你选的文件夹": "Launcher data, Java, games, mods and saves all go into the folder you choose",
"启动器数据和游戏都放进你选的文件夹": "Launcher data and games all go into the folder you choose",
"启动器数据在 AppData，游戏在系统的 .minecraft": "Launcher data in AppData, games in the system .minecraft",
"启动器数据在 AppData，游戏在系统的 .minecraft，和官方启动器一样": "Launcher data in AppData and games in the system .minecraft, just like the official launcher",
"启动器旁边的便携数据": "Portable data next to the launcher",
"启动器无法在这里保存数据（没有写入权限，例如放在 Program Files 里；或者所在的磁盘没有连接），这次已临时改用系统默认位置，关掉后这次的改动可能找不到。": "The launcher can't save data here (no write permission, for example in Program Files, or the drive isn't connected), so it's temporarily using the system default location; changes made this time may be missing after you close it.",
"启动器有新的更新内容": "The launcher has new updates",
"启动器没见过这个提示，下面是画面上的原文和截图，可以复制给别人帮忙看": "The launcher hasn't seen this prompt before. Below are the text on screen and a screenshot you can copy to ask someone for help",
"启动器的数据": "Launcher data",
"启动器的数据、下载的 Java 和账户放在哪里？": "Where should the launcher's data, downloaded Java and accounts go?",
"启动器的记录和缓存": "The launcher's records and caches",
"启动器的运行环境": "The launcher's runtime",
"启动器认不出现在的游戏画面。请点任务栏里的 Minecraft 切到游戏窗口看一眼（游戏会先开着），然后告诉启动器：": "The launcher can't recognize the current game screen. Click Minecraft in the taskbar to switch to the game window and take a look (the game stays open), then tell the launcher:",
"启动器认不出这里的情况：自动修复可能修不好，甚至带来新问题，所以不在「全部修复」里，确认后再点": "The launcher doesn't recognize the situation here: automatic fixes may not work or may cause new problems, so they're not in \"Fix all\"; confirm before clicking",
"启动器认不出，结果只是估计": "Not recognized by the launcher; results are only estimates",
"启动器设置": "launcher settings",
"启动器设置回到默认，做完自动重启并重新走一遍首次启动。": "Launcher settings go back to defaults; it restarts automatically and runs the first-launch setup again.",
"启动器设置已恢复默认。": "Launcher settings were restored to defaults.",
