"启动游戏、测试启动、一键 Debug、二分排查、建 MC 百科缓存的进度都在这里；下载任务在「下载 → 下载管理」": "Progress for launching, test launches, One-click Debug and bisect troubleshooting is all here; downloads are under \"Downloads → Download manager\"",
