"在主页依次按 ↑ ↑ ↓ ↓ ← → ← → B A 试试": "Try pressing ↑ ↑ ↓ ↓ ← → ← → B A on the home page",
"在主页显示 Minecraft 和启动器的更新日志。关闭后所有地方都不再显示，启动器更新后也不再提醒": "Shows Minecraft and launcher news on the home page. When off, it's hidden everywhere and launcher updates aren't announced either",
"在使用 {0} 之前，请仔细阅读以下声明。使用本启动器即表示你已阅读、理解并同意本声明的全部内容。": "Please read the following statement carefully before using {0}. Using the launcher means you have read, understood and agreed to all of it.",
