"外置登录账户的皮肤保存在 {0} 上，进它的服务器时大家都能看到。要换皮肤，请到它的网站上修改，改完回来点账户卡片上的「刷新」。": "Third-party accounts keep their skins on {0}, where everyone sees them on its servers. To change your skin, edit it on that site, then come back and click \"Refresh\" on the account card.",
"外置登录（LittleSkin 等认证服务器）时，你输入的用户名和密码只发送给你选择的认证服务器用于登录，本启动器不保存密码；登录令牌仅以系统加密方式保存在本机。": "For third-party sign-in (authentication servers such as LittleSkin), the username and password you enter are sent only to the authentication server you chose, to sign in; the launcher doesn't save the password, and sign-in tokens are stored only on this PC, encrypted by the system.",
