"把 {0}（{1}）移到回收站？依赖它的 Mod 可能会无法启动。": "Move {0} ({1}) to the Recycle Bin? Mods that depend on it may fail to start.",
"把 {from} 复制过去（{versions} 个版本、{saves} 个存档），原目录保持不动": "Copy {from} over ({versions} versions, {saves} saves); the original folder stays untouched",
"把「{0}」分配给账户": "Assign \"{0}\" to an account",
"把「{0}」恢复到这次修改之前（{1} · {2}）？这次换上的 Mod 会被换回原来的文件，被禁用的会重新启用。存档不会被改动，需要的话可以在「存档与备份」里恢复自动备份。": "Restore \"{0}\" to before this change ({1} · {2})? Mods swapped in this time go back to the original files and disabled ones are re-enabled. Saves aren't touched; you can restore an automatic backup in \"Saves & Backups\" if needed.",
"把「{0}」的设置同步到…": "Sync settings of \"{0}\" to…",
"把上次同步改过的文件放回原样？同步时新建的文件会删掉。": "Put the files changed by the last sync back the way they were? Files created by the sync will be deleted.",
"把世界带给哪个配置": "Which profile gets the worlds",
"把你已有的 Mod 列表导入{0}，配置器会为当前版本重新挑选合适的文件": "Import your existing mod list into {0}; the planner picks suitable files for the current version again",
"把公共目录的内容复制到 {0}": "Copy content from the shared folder to {0}",
"把启动器和它的数据（AuroraData 文件夹）复制到新文件夹，然后从新位置重新打开。原来的文件不会删除，确认新位置正常后可以自己删掉。": "Copies the launcher and its data (the AuroraData folder) to the new folder, then reopens from there. The original files aren't deleted; once the new location works, you can delete them yourself.",
"把启动器复制到新文件夹，然后从新位置重新打开。原来的文件不会删除，确认新位置正常后可以自己删掉。": "Copies the launcher to the new folder, then reopens from there. The original files aren't deleted; once the new location works, you can delete them yourself.",
"把存档导入 {0}": "Import saves into {0}",
"把当前启用状态保存为{0}…": "Save the current enabled state as {0}…",
"把当前游戏目录复制到 {0}，原目录保持不动{1}": "Copy the current game folder to {0}, leaving the original untouched{1}",
"把按键、灵敏度、画面等游戏里的设置记成一份「主档」，新配置自动套用，不同版本之间自动转换写法（例如 1.12 的数字按键 ↔ 新版的按键名）。写之前都会备份，可以撤销": "Keeps your in-game settings (keys, sensitivity, video and more) as one \"master copy\" that new profiles use automatically, converted between versions (for example 1.12 numeric key codes ↔ newer key names). Everything is backed up before writing and can be undone",
