"日志规则、二分排查、测试启动和硬件检测是自己写的。规则匹配的是游戏、Java 和加载器自己输出的报错原文，所以有些关键字和 HMCL、PCL2 的规则相同（例如 Pixel format not accelerated）": "The log rules, bisection, test launch and hardware checks were written for this project. The rules match the error text that the game, Java and the loaders print themselves, so some keywords are the same as in HMCL's and PCL2's rules (for example Pixel format not accelerated)",
