"显卡加速现在用不了（画面全靠处理器来画），动画会一卡一卡的，背景先定格成一张画面": "Graphics acceleration isn't available right now (the processor draws everything), so animation would stutter. The background is shown as a still picture for now",
"显卡厂商已经停止给这块显卡出新驱动，现在的驱动（{0}）旧是正常的。没装驱动或画面有问题时，到官网装它的最后一版驱动就行；它能跑的版本和画质都有限，见下面的负载估算": "The manufacturer no longer releases drivers for this card, so an old driver ({0}) is normal. If no driver is installed or the picture is wrong, install its last driver from the official site; the versions and quality it can handle are limited — see the load estimate below",
"显卡直通或带显卡的云电脑可以正常玩。画面很卡时，确认虚拟机里装的是显卡厂商的驱动（云电脑一般是云厂商提供的 NVIDIA GRID / vGPU 驱动）": "GPU passthrough or a cloud PC with a GPU plays fine. If it's very laggy, make sure the VM uses the graphics vendor's driver (cloud PCs usually use the provider's NVIDIA GRID / vGPU driver)",
"显卡驱动不支持 OpenGL：请更新显卡驱动，或确认没有使用基础显示适配器；如果正在用远程控制或串流软件，游戏窗口可能开在了它的虚拟显示器上，把主显示器换回电脑自己的屏幕再试": "The graphics driver doesn't support OpenGL: update the graphics driver and make sure you're not on the Basic Display Adapter. If you're using remote-control or streaming software, the game window may have opened on its virtual display; make your computer's own screen the main display and try again",
