"末影龙等你很久了": "The Ender Dragon has waited long enough",
"本启动器不包含、也不分发 Minecraft 游戏本体文件；游戏文件均由用户在使用时从 Mojang 官方服务器或用户自行选择的镜像源下载。用户应遵守《Minecraft 最终用户许可协议（EULA）》及 Mojang 的使用准则。离线模式仅为方便单人游戏与局域网游戏而提供，不构成对游戏的授权；作者支持并建议用户购买正版游戏。": "The launcher doesn't contain or distribute the Minecraft game files; they're downloaded by the user from Mojang's official servers or a mirror the user chooses. Users should follow the Minecraft End User License Agreement (EULA) and Mojang's usage guidelines. Offline mode is provided only for single-player and LAN play and doesn't grant a license to the game; the author supports and recommends buying the official game.",
"本启动器不提供任何广告位，不推荐、不推广任何服务器，也不与任何服务器、网站或商家存在合作或利益关系。": "The launcher has no ad slots, doesn't recommend or promote any server, and has no partnership or financial interest with any server, website or merchant.",
"本启动器不收集、不上传用户的个人信息与使用数据，不包含统计、追踪或遥测功能，没有自己的后台服务器，也不检测版本更新（新版本请到作者发布的 GitHub 仓库或其他发布位置自行获取）。": "The launcher doesn't collect or upload personal information or usage data, has no analytics, tracking or telemetry, no server of its own, and no update check (get new versions from the author's GitHub repository or other release locations).",
"本启动器为开源第三方项目，以 GNU 通用公共许可证第 3 版或（由你选择）任何更新的版本（GPL-3.0-or-later）发布，许可证全文见随程序附带的 LICENSE.txt。任何人均有权在遵守许可证的前提下使用、复制、修改与重新分发本项目；分发本项目或其修改版本时，必须保留版权声明与许可证文本，并按同一许可证提供完整的源代码。": "The launcher is an open-source third-party project released under the GNU General Public License, version 3 or (at your option) any later version (GPL-3.0-or-later); the full license text is in LICENSE.txt, which comes with the program. Anyone may use, copy, modify and redistribute this project under the license; whoever distributes it or a modified version must keep the copyright notice and license text and provide the complete source code under the same license.",
"本启动器使用的 Mojang 官方服务、BMCLAPI 等下载镜像、Modrinth、Eclipse Adoptium、Microsoft / Xbox 登录服务等均为第三方提供，其可用性、内容与服务条款由各自的提供方决定，作者不对其中断、变更或内容错误负责。": "The services the launcher uses — Mojang's official services, download mirrors like BMCLAPI, Modrinth, Eclipse Adoptium, Microsoft / Xbox sign-in and so on — are provided by third parties, whose availability, content and terms are up to each provider; the author isn't responsible for outages, changes or errors in them.",
"本启动器完全免费，作者从未以任何形式出售本启动器、收取激活费或提供付费“会员”“高级版”。": "The launcher is completely free. The author has never sold it in any form, charged activation fees, or offered paid \"memberships\" or \"premium editions\".",
"本启动器按“现状”提供，作者不对其功能的完整性、准确性、稳定性、安全性或适用于特定用途作任何明示或默示的保证。": "The launcher is provided \"as is\", without any express or implied warranty of completeness, accuracy, stability, security or fitness for a particular purpose.",
"本地 jar 会原样复制到 mods 文件夹（适合论坛下载的经典 Mod、自己开发的 Mod 等），安装后会自动检查并补齐缺失的前置": "Local jars are copied into the mods folder as is (good for classic mods from forums or mods you made yourself); missing dependencies are checked and filled in after installing",
"本地对照表没有，正在查 MC 百科…": "Not in the local name table; checking MC百科…",
"本地库加载失败：可能是 Java 架构与系统不匹配，或 natives 文件损坏": "Native library failed to load: Java's architecture may not match the system, or the natives are damaged",
"本地文件": "Local file",
"本地皮肤服务只在这台电脑上提供皮肤：单人游戏、你自己开的局域网里能看到；别人要看到你的皮肤，需要他们也装 CustomSkinLoader 之类的 Mod 并能读到你的皮肤": "The local skin service only provides skins on this PC: they show in single player and on LAN games you host; for others to see your skin, they need a mod like CustomSkinLoader that can read it",
"本地皮肤服务没有启动（{0}），这次游戏里看不到自定义皮肤": "The local skin service didn't start ({0}); the custom skin won't show in game this time",
"本地皮肤服务：{0}": "Local skin service: {0}",
"本声明任一条款被认定为无效或不可执行的，不影响其余条款的效力。": "If any clause of this statement is found invalid or unenforceable, the rest remain in effect.",
"本声明的译文仅供参考，与简体中文版有出入时，以简体中文版为准。": "This translation is for reference only. Where it differs from the Simplified Chinese version, the Simplified Chinese version prevails.",
