"树莓派、香橙派这类开发板跑的 Windows 一般没有显卡驱动（只有「基本显示适配器」），Minecraft 打不开或只能用处理器软件渲染，非常卡；这类板子更适合在 Linux 上跑社区移植版": "Windows on boards like Raspberry Pi or Orange Pi usually has no graphics driver (only \"Basic Display Adapter\"); Minecraft won't start or falls back to very slow CPU rendering. Community ports on Linux suit these boards better",
