"正版账户的皮肤保存在 Mojang 的服务器上，所有启动器和服务器都会看到。要换皮肤，请到 Minecraft 官网的个人资料页修改，改完回来点账户卡片上的「刷新」。": "Microsoft accounts keep their skins on Mojang's servers, seen by every launcher and server. To change your skin, edit it on the profile page of the Minecraft website, then come back and click \"Refresh\" on the account card.",
"正版账户的皮肤要上传到官方，不能在本地修改": "Skins of Microsoft accounts are uploaded to the official site and can't be changed locally",
"此版本暂无": "Not available for this version",
"每个游戏配置都可以单独指定 Java 和内存大小": "Each game profile can have its own Java and memory size",
"每个游戏配置都有自己的存档、资源包和光影，装 Mod 测试也不会弄坏别的配置的世界": "Each game profile has its own saves, resource packs and shaders, so testing mods won't break worlds in other profiles",
"每个配置拥有独立的 Mod、存档与设置，可以随时切换：纯净版、自己搭配的 Mod 配置、整合包…": "Each profile has its own mods, saves and settings and you can switch any time: vanilla, your own modded setups, modpacks…",
"每个配置每种自动备份只留最近几份，更早的自动删除。手动备份不会被自动删除": "Each profile keeps only the latest few automatic backups of each kind; older ones are deleted automatically. Manual backups are never deleted automatically",
"每个配置的世界": "Each profile's worlds",
"每个配置还可以在它的设置里单独选「不同步」": "Each profile can also choose \"Don't sync\" in its own settings",
"每次启动保持一致": "Keep the same on every launch",
"每次启动前写入；游戏里改了设置，退出后读回来，其他版本下次启动时也跟着变": "Written before every launch; settings you change in game are read back after you quit, and other versions follow on their next launch",
"每次启动前复制来源的存档与配置，游戏只修改副本——测试 Mod 更新或新版本，原存档完全不受影响": "Copies the source's saves and configs before every launch, and the game only changes the copy — test mod updates or new versions without touching the original saves at all",
"每次启动前把这个配置的世界备份一份（存档没变就跳过）。存档大时会让启动慢一些": "Backs up this profile's worlds before every launch (skipped if the saves haven't changed). Large saves make launching a bit slower",
"每次启动复制所选配置的存档，测试时不会改动原存档": "Copies the chosen profile's saves on every launch; testing won't change the original saves",
"每次启动复制来源的存档，不会修改原存档": "Copies the source's saves on every launch without modifying them",
"每次启动重新复制": "Copy again on every launch",
"每次询问": "Ask every time",
"每行一个，支持：": "One per line. Supports:",
"每行一个，支持：\nSodium\nhttps://modrinth.com/mod/lithium\nxaeros-minimap\njei-1.20.1-forge-15.2.0.27.jar\n\n也可以粘贴从其他启动器导出的 Mod 列表": "One per line, accepts:\nSodium\nhttps://modrinth.com/mod/lithium\nxaeros-minimap\njei-1.20.1-forge-15.2.0.27.jar\n\nYou can also paste a mod list exported from another launcher",
"比如便携版的 AuroraData 文件夹、旧电脑拷过来的数据文件夹": "For example a portable edition's AuroraData folder, or a data folder copied from an old PC",
