"用「转为正式配置」：把现在用的存档、Mod 配置、游戏选项、光影包都留成这个配置自己的。直接选「完全独立」会回到切换之前这个配置自己的内容（可能是空的）": "Use \"Convert to full profile\" to keep the saves, mod configs, game options and shader packs in use now as this profile's own. Choosing \"Fully separate\" directly goes back to this profile's own content from before the switch (which may be empty)",
