"让启动器更省资源：关掉动画、毛玻璃、阴影、3D 皮肤预览、背景音乐和音效、主页更新日志和硬件加速（重启后生效），主页背景变成静止的画面。页面都还在，配置比较低的电脑推荐打开": "Makes the launcher use fewer resources: turns off animations, blur, shadows, the 3D skin preview, background music and sound effects, the home news panel and hardware acceleration (after restart), and the home background becomes a still picture. All pages stay; recommended for low-end PCs",
"让启动器跑得更省：关掉动画、毛玻璃、阴影、3D 皮肤预览、背景音乐和主页的更新日志，主页背景变成静止的画面，并关闭硬件加速（重启后生效）。所有页面都还在。适合配置比较低的电脑。": "Makes the launcher lighter: turns off animations, blur, shadows, the 3D skin preview, background music and the home news panel, the home background becomes a still picture, and hardware acceleration turns off (after restart). All pages stay. Good for low-end PCs.",
