"远古 Beta": "Old Beta",
"远古时代": "Ancient times",
"远古版": "Old versions",
"远古版本只能以原版运行。": "Old versions can only run vanilla.",
"远程桌面默认不让程序用显卡，Minecraft 会报「不支持 OpenGL」之类的错误打不开，或者非常卡。可以在这台电脑本机上玩；或者改用 Parsec、Moonlight + Sunshine、向日葵、ToDesk 这类串流软件；或者在这台电脑的组策略里打开「对所有远程桌面服务会话使用硬件图形适配器」（gpedit.msc → 计算机配置 → 管理模板 → Windows 组件 → 远程桌面服务 → 远程桌面会话主机 → 远程会话环境）": "Remote Desktop doesn't let programs use the graphics card by default, so Minecraft reports errors like \"OpenGL not supported\" and won't start, or runs very slowly. Play on this PC directly; or use streaming software such as Parsec, Moonlight + Sunshine, Sunlogin or ToDesk; or enable \"Use hardware graphics adapters for all Remote Desktop Services sessions\" in this PC's Group Policy (gpedit.msc → Computer Configuration → Administrative Templates → Windows Components → Remote Desktop Services → Remote Desktop Session Host → Remote Session Environment)",
"连同 Mod 配置": "Including mod configs",
