"选一个游戏配置做全面检测：Java、内存、磁盘、显卡与硬件、文件完整性、设置与按键、Mod 兼容性，最后真的测试启动一次。发现问题可以一键修复，Mod 的问题交给一键 Debug 自动排查": "Pick a profile for a full check: Java, memory, disk, graphics & hardware, file integrity, settings & keys, mod compatibility, and finally an actual test launch. Problems can be fixed in one click, and mod problems are handed to One-click Debug",
"选你平时玩得最多、设置调得最顺手的那个。按键、画面、声音等都会读进主档；Mod 按键、服务器列表、Mod 配置文件也会一起存着，用不用看「同步哪些」的勾选": "Pick the one you play most, with the settings you like best. Keys, video, sound and more go into the master copy; mod keys, the server list and mod configs are stored too and used according to \"What to sync\"",
