"通过本启动器浏览、下载或安装的 Mod、整合包、资源包、光影包、Java 运行时等内容，其著作权与许可协议归各自作者或权利人所有。本启动器仅提供获取途径，不对这些内容的合法性、安全性、可用性与兼容性作任何保证；用户应自行遵守其许可协议。": "Copyright and licenses of mods, modpacks, resource packs, shader packs, Java runtimes and other content browsed, downloaded or installed through the launcher belong to their authors or right holders. The launcher only provides a way to get them and makes no guarantee about their legality, safety, availability or compatibility; users should follow their licenses.",
